struct PolygonWithHoles2d {
    std::vector<cg3::Point2d> outerBoundary;
    std::vector<std::vector<cg3::Point2d>> holes;
};

std::vector<PolygonWithHoles2d> intersection2D(const std::vector<cg3::Point2d>& P1, const std::vector<cg3::Point2d>& P2) {
    auto convertPoint = [](const cg3::Point2d& p) { return Point_2(p.x(), p.y()); };

    Polygon_2 cgalPolygon1, cgalPolygon2;
    for (const auto& p : P1) {
        cgalPolygon1.push_back(convertPoint(p));
    }
    for (const auto& p : P2) {
        cgalPolygon2.push_back(convertPoint(p));
    }

    Pwh_list_2 intersectionResults;
    CGAL::intersection(cgalPolygon1, cgalPolygon2, std::back_inserter(intersectionResults));

    std::vector<PolygonWithHoles2d> result;
    for (const auto& pwh : intersectionResults) {
        PolygonWithHoles2d pwh2d;
        for (const auto& p : pwh.outer_boundary()) {
            pwh2d.outerBoundary.push_back(cg3::Point2d(CGAL::to_double(p.x()), CGAL::to_double(p.y())));
        }
        for (const auto& hole : pwh.holes()) {
            std::vector<cg3::Point2d> holePoints;
            for (const auto& p : hole) {
                holePoints.push_back(cg3::Point2d(CGAL::to_double(p.x()), CGAL::to_double(p.y())));
            }
            pwh2d.holes.push_back(holePoints);
        }
        result.push_back(pwh2d);
    }

    return result;
}

